// Bounded text-generation subset of the SAS macro facility. No eval.
const nameRE=/^[a-z_]\w*$/i;
function error(msg){throw new Error('Macro: '+msg)}
function quotedEnd(s,i){const quote=s[i++];while(i<s.length){if(s[i]===quote){if(s[i+1]===quote)i+=2;else return i+1}else i++}error('Unclosed quoted text')}
