 if(w==='macro'){let name=this.word();this.skip();let params=this.s[this.i]==='('?splitArgs(this.parent()):[];if(params.length===1&&params[0]==='')params=[];let seenKeyword=false,seen=new Set();params=params.map(p=>{let m=p.match(/^([a-z_]\w*)(?:\s*=([\s\S]*))?$/i);if(!m)error('Unsupported macro parameter '+p);let n=m[1].toLowerCase(),keyword=m[2]!==undefined;if(seen.has(n))error('Repeated macro parameter '+n);seen.add(n);if(seenKeyword&&!keyword)error('Positional parameters must precede keyword parameters');seenKeyword ||= keyword;return{name:n,keyword,value:m[2]??''}});this.semi();let body=this.list(['mend']);this.i+=5;let suffix=this.throughSemi().trim();if(suffix&&suffix.toLowerCase()!==name)error('%MEND name does not match '+name);return{k:'def',name,params,body}}
